using Mentorly.Domain.Entities; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace Mentorly.Infrastructure.Persistence.Configurations;
public sealed class QuizQuestionConfiguration : IEntityTypeConfiguration<QuizQuestion> { public void Configure(EntityTypeBuilder<QuizQuestion> b) { b.ToTable("quiz_questions"); b.HasKey(x=>x.Id); b.Property(x=>x.Id).HasColumnName("id"); b.Property(x=>x.ActivityId).HasColumnName("activity_id"); b.Property(x=>x.Prompt).HasColumnName("prompt").HasMaxLength(1000); b.Property(x=>x.CorrectAnswer).HasColumnName("correct_answer").HasMaxLength(500); b.Property(x=>x.OrderIndex).HasColumnName("order_index"); b.HasIndex(x=>new{x.ActivityId,x.OrderIndex}); } }
public sealed class QuizAttemptConfiguration : IEntityTypeConfiguration<QuizAttempt> { public void Configure(EntityTypeBuilder<QuizAttempt> b) { b.ToTable("quiz_attempts"); b.HasKey(x=>x.Id); b.Property(x=>x.Id).HasColumnName("id"); b.Property(x=>x.EnrollmentId).HasColumnName("enrollment_id"); b.Property(x=>x.ActivityId).HasColumnName("activity_id"); b.Property(x=>x.Score).HasColumnName("score"); b.Property(x=>x.Passed).HasColumnName("passed"); b.Property(x=>x.SubmittedAt).HasColumnName("submitted_at"); b.HasIndex(x=>new{x.EnrollmentId,x.ActivityId}); } }
